   1| // Cursor pagination shared by every collection GET.
   2| import { z } from "zod";
   3| import { HttpProblem } from "./problem.ts";
   4| 
   5| export const CursorQuery = z.object({
   6|   cursor: z.string().min(1).optional(),
   7|   limit: z.coerce.number().int().min(1).max(100).default(20),
   8| });
   9| export type CursorQuery = z.infer<typeof CursorQuery>;
  10| 
  11| export const encodeCursor = (id: string): string => Buffer.from(id, "utf8").toString("base64url");
  12| export const decodeCursor = (cursor: string): string => Buffer.from(cursor, "base64url").toString("utf8");
  13| 
  14| export function pageOf<T extends z.ZodType>(item: T) {
  15|   return z.object({ data: z.array(item), nextCursor: z.string().nullable() });
  16| }
  17| 
  18| export function paginate<T extends { id: string }>(
  19|   items: readonly T[],
  20|   query: { cursor?: string | undefined; limit: number },
  21| ): { data: T[]; nextCursor: string | null } {
  22|   let start = 0;
  23|   if (query.cursor !== undefined) {
  24|     const afterId = decodeCursor(query.cursor);
  25|     const index = items.findIndex((i) => i.id === afterId);
  26|     if (index === -1) throw new HttpProblem(422, "Invalid cursor", "cursor does not match any item", "validation");
  27|     start = index + 1;
  28|   }
  29|   const data = items.slice(start, start + query.limit);
  30|   const last = data[data.length - 1];
  31|   const nextCursor = last !== undefined && start + query.limit < items.length ? encodeCursor(last.id) : null;
  32|   return { data, nextCursor };
  33| }
